            "p": "राशि संगतता जन्म वर्षों की शाखाओं को साथ-साथ रखती है, और दिन शाखा संगतता जन्म दिनों की शाखाओं को। दोनों अलग शाखाएँ हो सकती हैं, इसलिए वही दो लोग दोनों में अलग-अलग संबंध दिखा सकते हैं।"
